    41  /* On failure return, we update *NEXT to point back at OFFSET.  */
    42  static inline Elf *
    43  do_fail (int error, off_t *next, off_t offset)
    44  {
    45      if (next != NULL)
    46        *next = offset;
    47      //__libelf_seterrno (error);
    48      __libdwfl_seterrno (DWFL_E (LIBELF, error));
    49      return NULL;
    50  }
